mapper.insert:

    SELECT
        'SLRY'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(SALARY_ID), LENGTH('SLRY' ) + 1)), 0) + 1, 6, '0')
    FROM SALARY

INSERT INTO SALARY (
		SALARY_ID
		, USER_ID
		, CODE_DETAIL_NO
		, SALARY_MIN
		, SALARY_MAX
		, CREATE_DATE
	) VALUES (
	#{salaryId}
		, #{userId}
		, #{codeDetailNo}
		, #{salaryMin}
		, #{salaryMax}
		, SYSDATE
)

mapper.select:
SELECT * FROM ( SELECT ROWNUM rnum, a.* FROM ( SELECT C.INDUSTRY_TYPE, C.COM_NAME, C.COM_MEM, C.COM_LOGO, C.USER_ID, ROUND(AVG((TO_NUMBER(S.SALARY_MIN) + TO_NUMBER(S.SALARY_MAX)) / 2), 0) AS SALARY_AVG FROM COMPANY C LEFT JOIN SALARY S ON C.USER_ID = S.USER_ID AND TO_NUMBER(SUBSTR(S.CODE_DETAIL_NO, 6)) BETWEEN 1 AND 6 WHERE 1=1
AND C.COM_NAME LIKE '%' || #{keyword} || '%'
GROUP BY C.INDUSTRY_TYPE, C.COM_NAME, C.COM_MEM, C.COM_LOGO, C.USER_ID
HAVING 1=1
AND ROUND(AVG((TO_NUMBER(S.SALARY_MIN) + TO_NUMBER(S.SALARY_MAX)) / 2),0) >= #{minSalary}
AND ROUND(AVG((TO_NUMBER(S.SALARY_MIN) + TO_NUMBER(S.SALARY_MAX)) / 2),0) <= #{maxSalary}
ORDER BY
SALARY_AVG DESC
SALARY_AVG ASC
C.COM_NAME
) a WHERE ROWNUM <= #{endRow} ) WHERE rnum > #{startRow}

SELECT COUNT(*) FROM ( SELECT C.USER_ID FROM COMPANY C LEFT JOIN SALARY S ON C.USER_ID = S.USER_ID AND TO_NUMBER(SUBSTR(S.CODE_DETAIL_NO, 6)) BETWEEN 1 AND 6 WHERE 1=1
AND UPPER(C.COM_NAME) LIKE UPPER('%' || #{keyword} || '%')
GROUP BY C.USER_ID HAVING 1=1
AND ROUND(AVG((TO_NUMBER(S.SALARY_MIN) + TO_NUMBER(S.SALARY_MAX)) / 2),0) >= #{minSalary}
AND ROUND(AVG((TO_NUMBER(S.SALARY_MIN) + TO_NUMBER(S.SALARY_MAX)) / 2),0) <= #{maxSalary}
)
